  [81866] = { "Feralas任務XI：Greater Moonstone", "Feralas Nightmare IncursionsでGreater Moonstoneを$N1個集め、Field Captain Arunnelのところへ戻って下さい。", "悪魔どもがここで我々の気を引いている間に、Emerald Dreamは悪夢へと堕落させられつつある。急いでDream BoughのEmerald Dream Portalを通り、Nightmare Incursionsの中からGreater Moonstoneを集めてきてくれ。その魔力を利用すれば、被害を元に戻せる。採掘者の助けが必要になるだろう。", nil, nil, 0x2963789b, 0x8292fbca, 0x91b6d263, nil, nil, "...mm" },
  [81867] = { "Feralas任務XII：Greater Moondragon Scales", "Feralas Nightmare IncursionsでMoondragon Scalesを$N1個集め、Field Captain Arunnelのところへ戻って下さい。", "悪魔どもがここで我々の気を引いている間に、Emerald Dreamは悪夢へと堕落させられつつある。急いでDream BoughのEmerald Dream Portalを通り、Nightmare Incursionsの中のdragonkinからMoondragon Scalesを集めてきてくれ。その魔力を利用すれば、被害を元に戻せる。皮はぎ職人の助けが必要になるだろう。", nil, nil, 0x5f666de3, 0xf98d7de5, 0x4ea05055, nil, nil, "...mm" },
  [81868] = { "Feralas任務XIII：Tyrannikus討伐", "Oneirosの荒れた神殿のFeralas Nightmare IncursionでTyrannikusを倒し、Field Captain Arunnelのところへ戻って下さい。", "悪魔どもがここで我々の気を引いている間に、Emerald Dreamは悪夢へと堕落させられつつある。急いでDream BoughのEmerald Dream Portalを通り、OneirosのNightmare Incursionへ向かってくれ。そこでドラゴンのTyrannikusを倒し、私のもとへ戻ってくれ。", nil, nil, 0x0c867189, 0x0bc00c00, 0xca79d1ba, nil, nil, "...mm" },
  [81870] = { "Feralas任務XIV：Alondrius討伐", "Twin Colossalsの道を巡回しているFeralas Nightmare IncursionのAlondriusを倒し、Field Captain Arunnelのところへ戻って下さい。", "悪魔どもがここで我々の気を引いている間に、Emerald Dreamは悪夢へと堕落させられつつある。急いでDream BoughのEmerald Dream Portalを通り、Twin ColossalsのNightmare Incursionへ向かってくれ。そこで森の守り手Alondriusを倒し、私のもとへ戻ってくれ。", nil, nil, 0xa7166c87, 0x016052fe, 0x86312dde, nil, nil, "...mm" },
  [81871] = { "Feralas任務XV：Slirena討伐", "Ruins of Ravenwindのジッグラトの近くのFeralas Nightmare IncursionでSlirenaを倒し、Field Captain Arunnelのところへ戻って下さい。", "悪魔どもがここで我々の気を引いている間に、Emerald Dreamは悪夢へと堕落させられつつある。急いでDream BoughのEmerald Dream Portalを通り、Ruins of RavenwindのNightmare Incursionへ向かってくれ。そこでharpyの「女王」Slirenaを倒し、私のもとへ戻ってくれ。", nil, nil, 0x8a3b136b, 0x866b0a0d, 0xeabbac63, nil, nil, "...mm" },
  [81872] = { "Feralas任務XVI：Mellias Earthtender救出", "OneirosのJademir Lakeのそばの階段のFeralas Nightmare IncursionからMellias Earthtenderを救出し、Field Captain Arunnelのところへ戻って下さい。", "悪魔どもがここで我々の気を引いている間に、Emerald Dreamは悪夢へと堕落させられつつある。急いでDream BoughのEmerald Dream Portalを通り、OneirosのNightmare Incursionへ向かってくれ。そこで眠っているDruid of the Claw Mellias Earthtenderを見つけ、彼を安全な場所まで護衛してくれ。それから私のもとへ戻ってくれ。", nil, nil, 0xc95806e6, 0x9b07b428, 0x9b0c0c0b, nil, nil, "...mm" },
  [81873] = { "Feralas任務XVII：Nerene Brooksinger救出", "Twin Colossalsのたき火のFeralas Nightmare IncursionからNerene Brooksingerを救出し、Field Captain Arunnelのところへ戻って下さい。", "悪魔どもがここで我々の気を引いている間に、Emerald Dreamは悪夢へと堕落させられつつある。急いでDream BoughのEmerald Dream Portalを通り、Twin ColossalsのNightmare Incursionへ向かってくれ。そこで眠っているDruid of the Claw Nerene Brooksingerを見つけ、彼女を安全な場所まで護衛してくれ。それから私のもとへ戻ってくれ。", nil, nil, 0x8d91efc0, 0x06966099, 0xaf96a9fe, nil, nil, "...mm" },
  [81874] = { "Feralas任務XVIII：Jamniss Treemender救出", "Ruins of Ravenwindの北端のFeralas Nightmare IncursionからJamnice Treemenderを救出し、Field Captain Arunnelのところへ戻って下さい。", "悪魔どもがここで我々の気を引いている間に、Emerald Dreamは悪夢へと堕落させられつつある。急いでDream BoughのEmerald Dream Portalを通り、Ruins of RavenwindのNightmare Incursionへ向かってくれ。そこで眠っているDruid of the Claw Jamnice Treemenderを見つけ、彼女を安全な場所まで護衛してくれ。それから私のもとへ戻ってくれ。", nil, nil, 0xf0855feb, 0xa6ed25e8, 0x240a63e6, nil, nil, "...mm" },
